import json
from itertools import permutations

def solve():
    houses = [1, 2, 3, 4]
    names = ['Peter', 'Alice', 'Eric', 'Arnold']
    mothers = ['Janelle', 'Holly', 'Aniya', 'Kailyn']
    smoothies = ['watermelon', 'dragonfruit', 'desert', 'cherry']
    heights = ['tall', 'average', 'short', 'very short']
    education = ['high school', 'associate', 'master', 'bachelor']

    solutions = []

    for mothers_perm in permutations(mothers):
        # 1. Mother Janelle in the third house
        if mothers_perm[2] != 'Janelle':
            continue

        for heights_perm in permutations(heights):
            # 9 + 1 imply tall is at house 3 (index 2)
            if heights_perm[2] != 'tall':
                continue

            for names_perm in permutations(names):
                # 12. Tall is Alice -> Alice in house 3
                if names_perm[2] != 'Alice':
                    continue

                # 10. Arnold right of average
                if names_perm.index('Arnold') <= heights_perm.index('average'):
                    continue

                for edu_perm in permutations(education):
                    # 6. High school not in the third house
                    if edu_perm[2] == 'high school':
                        continue

                    # 7. Mother Kailyn is associate
                    if edu_perm[mothers_perm.index('Kailyn')] != 'associate':
                        continue

                    # 2+3: Desert = master; Desert not in first house -> master not in first house
                    if edu_perm[0] == 'master':
                        continue

                    # 4. Very short left of high school
                    if heights_perm.index('very short') >= edu_perm.index('high school'):
                        continue

                    for smoothies_perm in permutations(smoothies):
                        # 3. Desert not in first house
                        if smoothies_perm[0] == 'desert':
                            continue

                        # 2. Desert = master
                        if smoothies_perm[edu_perm.index('master')] != 'desert':
                            continue

                        # 11. Dragonfruit directly left of short
                        if smoothies_perm.index('dragonfruit') + 1 != heights_perm.index('short'):
                            continue

                        # 5. Eric next to Cherry
                        if abs(names_perm.index('Eric') - smoothies_perm.index('cherry')) != 1:
                            continue

                        # 8. Cherry = Aniya
                        if smoothies_perm[mothers_perm.index('Aniya')] != 'cherry':
                            continue

                        # 9. Tall = Janelle (already implied but we ensure consistency)
                        if heights_perm[mothers_perm.index('Janelle')] != 'tall':
                            continue

                        # All constraints satisfied; record solution
                        sol_rows = []
                        for i in range(4):
                            sol_rows.append([
                                str(i+1),
                                names_perm[i],
                                mothers_perm[i],
                                smoothies_perm[i],
                                heights_perm[i],
                                edu_perm[i]
                            ])
                        solutions.append(sol_rows)

    # Prepare JSON output
    header = ["House", "Name", "Mother", "Smoothie", "Height", "Education"]
    # Assume unique or use the first solution
    result = {
        "solution": {
            "header": header,
            "rows": solutions[0] if solutions else []
        }
    }
    return json.dumps(result, ensure_ascii=False, indent=2)

if __name__ == "__main__":
    print(solve())
